window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-03c3afffec9b27c2"]={"versions": [{"id": "FIG-03c3afffec9b27c2", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Instanzendiagramm / AUTOSAR-Objektdiagramm (M2/M1-Ausschnitt der Software Component Template, TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (VFB- und BSW-Interaktionsebene), Kapitel 11 (<em>NV Data Handling</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der formalen Disambiguierung für die RTE- und BSW-Generierung, wenn derselbe persistente Speicherblock (<code>NvBlockDescriptor</code>) über verschiedene Ports/Events mit divergierenden Persistierungsstrategien (sofortiges Schreiben vs. Schreiben beim Herunterfahren) angesteuert wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>NvBlockSwComponentType</code>:</strong> Kapselnder SW-C-Typ, der den NVRAM-Blockzugriff und dessen RAM-Mirror verwaltet und Schnittstellen zu Application-SWCs und dem NVRAM Manager (NvM) bereitstellt.</li>\n<li><strong><code>NvBlockDescriptor</code> (Name: <code>\"nvBlock\"</code>):</strong> Zentrales Deskriptor-Element zur statischen Definition der NV-Blockeigenschaften innerhalb der SW-C.</li>\n<li>Aggregiert zwei <code>NvBlockDataMapping</code>-Instanzen (<code>\"X\"</code> und <code>\"Y\"</code>).</li>\n<li>Aggregiert zwei <code>RoleBasedDataAssignment</code>-Instanzen.</li>\n<li>Aggregiert / referenziert <code>NvBlockNeeds</code> (<code>\"nvBlock\"</code>).</li>\n<li><strong>Ports & Datenelemente (<code>DE1</code>):</strong></li>\n<li><strong>Port X (Blau):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Shutdown-Speicherung).</li>\n<li><strong>Port Y (Orange):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Sofortspeicherung).</li>\n<li><strong><code>NvBlockNeeds</code> (Name: <code>\"nvBlock\"</code>):</strong> BSW-Service-Bedarfsdeklaration an den NvM mit widersprüchlichen bzw. parallelen Anforderungen:</li>\n<li><code>storeAtShutdown = True</code></li>\n<li><code>storeImmediately = True</code></li>\n<li><strong><code>RoleBasedDataAssignment</code> (Disambiguierungs-Entitäten gem. <code>TPS_SWCT_01586</code>):</strong></li>\n<li><code>role = \"storeAtShutdown\"</code>: Bindet das Datenelement <code>DE1</code> von Port X an die Shutdown-Strategie von <code>NvBlockNeeds</code>.</li>\n<li><code>role = \"storeImmediately\"</code>: Bindet das Datenelement <code>DE1</code> von Port Y an die Immediate-Schreibstrategie von <code>NvBlockNeeds</code>.</li>\n<li><strong>RTE-Events & Runnables:</strong></li>\n<li><code>DataReceivedEvent</code> <code>\"X\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Shutdown\"</code> bei Datenempfang an Port X.</li>\n<li><code>DataReceivedEvent</code> <code>\"Y\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Immediate\"</code> bei Datenempfang an Port Y.</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>NvBlockDataMapping</code> (Mapping von mehreren Port-Datenelementen auf denselben NV-Block).</li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>RoleBasedDataAssignment</code> (Eindeutige Rollenzuweisung pro Port-Datenelement).</li>\n<li><code>DataReceivedEvent</code> referenziert das jeweilige <code>VariableDataPrototype</code> (<code>DE1</code>) am Port und triggert die zugeordnete <code>RunnableEntity</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Pfad X: Pufferung / Store-at-Shutdown (Blau)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port X (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"X\"</code> löst <code>RunnableEntity \"Shutdown\"</code> aus.</li>\n<li><strong>RAM-Update:</strong> Die Runnable liest <code>DE1</code> via RTE-API und aktualisiert den lokalen RAM-Spiegel des <code>NvBlockDescriptor</code>.</li>\n<li><strong>Kein NvM-Trigger:</strong> Es wird <em>kein</em> Sofortschreibauftrag (<code>NvM_WriteBlock</code>) an den NvM abgesetzt.</li>\n<li><strong>Persistierung:</strong> Der Block wird erst im Steuergeräte-Nachlauf (ECU Shutdown via <code>BswM</code>/<code>EcuM</code>) über den globalen Sammelauftrag <code>NvM_WriteAll</code> in das nichtflüchtige Medium (Flash/EEPROM) geschrieben.</li>\n</ol>\n<p class=\"fig-p\">#### Pfad Y: Sofortige Persistierung / Store-Immediately (Orange)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port Y (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"Y\"</code> löst <code>RunnableEntity \"Immediate\"</code> aus.</li>\n<li><strong>RAM-Update & NvM-Schreibauftrag:</strong> Die Runnable liest <code>DE1</code>, aktualisiert den RAM-Spiegel und setzt über die RTE unmittelbar einen asynchronen Schreibauftrag (<code>NvM_WriteBlock</code> / Service-Port <code>NvMService</code>) ab.</li>\n<li><strong>Verarbeitung:</strong> Der NvM reiht den Request in seine interne Prioritäts-Queue ein und führt den Schreibvorgang via MemIf/Fee/Fls direkt im laufenden Betriebszyklus aus.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgabe (<code>TPS_SWCT_01586</code>):</strong></li>\n</ul>\n<p class=\"fig-p\">Wenn für denselben <code>NvBlockDescriptor</code> in <code>NvBlockNeeds</code> mehrere event-basierte Speicherstrategien (<code>storeImmediately=True</code> und <code>storeAtShutdown=True</code>) gleichzeitig deklariert sind, <strong>muss</strong> für jedes beteiligte Datenelement ein <code>RoleBasedDataAssignment</code> mit den exakten normativen Rollennamen (<code>storeImmediately</code> bzw. <code>storeAtShutdown</code>) definiert werden. Fehlt diese Zuordnung, schlägt die Validierung des ARXML-Modells fehl, da der RTE-Generator das Verhalten nicht deterministisch auflösen kann.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Generatorkonsequenz:</strong></li>\n<li>Anhand der Rolle <code>storeImmediately</code> generiert die RTE in der zugehörigen Runnable (<code>Immediate</code>) bzw. im Komponenten-Wrapper den API-Aufruf zur Beauftragung des NvM.</li>\n<li>Fehlt das Mapping, generiert der Generator entweder redundante/zyklische Schreibzugriffe oder unterlässt den Sofortschreibauftrag vollständig.</li>\n<li><strong>Nebenläufigkeit & Datenintegrität (Concurrency):</strong></li>\n</ul>\n<p class=\"fig-p\">Da beide Runnables (<code>Shutdown</code> und <code>Immediate</code>) auf denselben RAM-Spiegel des <code>NvBlockDescriptor</code> schreiben, müssen im RTE-Vertrag Schutzmechanismen (z. B. <em>Exclusive Areas</em> / Inter-Runnable Resource Locks) konfiguriert werden, um Race Conditions und inkonsistente Zwischenstände bei gleichzeitiger Ausführung zu verhindern.</p>\n<ul class=\"fig-list\">\n<li><strong>Embedded Flash Endurance (Wear-Out):</strong></li>\n</ul>\n<p class=\"fig-p\">Port Y darf im Applikationsdesign nur für seltene, zwingend absturzfeste Events (z. B. Crash-Signale, kritische Fehler/DTCs, initiale Kalibrierungen) verwendet werden. Ein hochfrequentes Senden auf Port Y führt durch die <code>storeImmediately</code>-Eigenschaft zur schnellen Erschöpfung der Flash-Löschzyklen (Endurance Limit von EEPROM/Data-Flash). Port X ist für zyklisch/häufig fluktuierende Werte zu nutzen.</p>"}, {"id": "FIG-419831fa6ee6f5c9", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Instanzendiagramm / AUTOSAR-Objektdiagramm (M2/M1-Ausschnitt der Software Component Template, TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (VFB- und BSW-Interaktionsebene), Kapitel 11 (<em>NV Data Handling</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der formalen Disambiguierung für die RTE- und BSW-Generierung, wenn derselbe persistente Speicherblock (<code>NvBlockDescriptor</code>) über verschiedene Ports/Events mit divergierenden Persistierungsstrategien (sofortiges Schreiben vs. Schreiben beim Herunterfahren) angesteuert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>NvBlockSwComponentType</code>:</strong> Kapselnder SW-C-Typ, der den NVRAM-Blockzugriff und dessen RAM-Mirror verwaltet und Schnittstellen zu Application-SWCs und dem NVRAM Manager (NvM) bereitstellt.</li>\n<li><strong><code>NvBlockDescriptor</code> (Name: <code>\"nvBlock\"</code>):</strong> Zentrales Deskriptor-Element zur statischen Definition der NV-Blockeigenschaften innerhalb der SW-C.</li>\n<li>Aggregiert zwei <code>NvBlockDataMapping</code>-Instanzen (<code>\"X\"</code> und <code>\"Y\"</code>).</li>\n<li>Aggregiert zwei <code>RoleBasedDataAssignment</code>-Instanzen.</li>\n<li>Aggregiert / referenziert <code>NvBlockNeeds</code> (<code>\"nvBlock\"</code>).</li>\n<li><strong>Ports & Datenelemente (<code>DE1</code>):</strong></li>\n<li><strong>Port X (Blau):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Shutdown-Speicherung).</li>\n<li><strong>Port Y (Orange):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Sofortspeicherung).</li>\n<li><strong><code>NvBlockNeeds</code> (Name: <code>\"nvBlock\"</code>):</strong> BSW-Service-Bedarfsdeklaration an den NvM mit widersprüchlichen bzw. parallelen Anforderungen:</li>\n<li><code>storeAtShutdown = True</code></li>\n<li><code>storeImmediately = True</code></li>\n<li><strong><code>RoleBasedDataAssignment</code> (Disambiguierungs-Entitäten gem. <code>TPS_SWCT_01586</code>):</strong></li>\n<li><code>role = \"storeAtShutdown\"</code>: Bindet das Datenelement <code>DE1</code> von Port X an die Shutdown-Strategie von <code>NvBlockNeeds</code>.</li>\n<li><code>role = \"storeImmediately\"</code>: Bindet das Datenelement <code>DE1</code> von Port Y an die Immediate-Schreibstrategie von <code>NvBlockNeeds</code>.</li>\n<li><strong>RTE-Events & Runnables:</strong></li>\n<li><code>DataReceivedEvent</code> <code>\"X\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Shutdown\"</code> bei Datenempfang an Port X.</li>\n<li><code>DataReceivedEvent</code> <code>\"Y\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Immediate\"</code> bei Datenempfang an Port Y.</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>NvBlockDataMapping</code> (Mapping von mehreren Port-Datenelementen auf denselben NV-Block).</li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>RoleBasedDataAssignment</code> (Eindeutige Rollenzuweisung pro Port-Datenelement).</li>\n<li><code>DataReceivedEvent</code> referenziert das jeweilige <code>VariableDataPrototype</code> (<code>DE1</code>) am Port und triggert die zugeordnete <code>RunnableEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Pfad X: Pufferung / Store-at-Shutdown (Blau)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port X (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"X\"</code> löst <code>RunnableEntity \"Shutdown\"</code> aus.</li>\n<li><strong>RAM-Update:</strong> Die Runnable liest <code>DE1</code> via RTE-API und aktualisiert den lokalen RAM-Spiegel des <code>NvBlockDescriptor</code>.</li>\n<li><strong>Kein NvM-Trigger:</strong> Es wird <em>kein</em> Sofortschreibauftrag (<code>NvM_WriteBlock</code>) an den NvM abgesetzt.</li>\n<li><strong>Persistierung:</strong> Der Block wird erst im Steuergeräte-Nachlauf (ECU Shutdown via <code>BswM</code>/<code>EcuM</code>) über den globalen Sammelauftrag <code>NvM_WriteAll</code> in das nichtflüchtige Medium (Flash/EEPROM) geschrieben.</li>\n</ol>\n<p class=\"fig-p\">#### Pfad Y: Sofortige Persistierung / Store-Immediately (Orange)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port Y (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"Y\"</code> löst <code>RunnableEntity \"Immediate\"</code> aus.</li>\n<li><strong>RAM-Update & NvM-Schreibauftrag:</strong> Die Runnable liest <code>DE1</code>, aktualisiert den RAM-Spiegel und setzt über die RTE unmittelbar einen asynchronen Schreibauftrag (<code>NvM_WriteBlock</code> / Service-Port <code>NvMService</code>) ab.</li>\n<li><strong>Verarbeitung:</strong> Der NvM reiht den Request in seine interne Prioritäts-Queue ein und führt den Schreibvorgang via MemIf/Fee/Fls direkt im laufenden Betriebszyklus aus.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgabe (<code>TPS_SWCT_01586</code>):</strong></li>\n</ul>\n<p class=\"fig-p\">Wenn für denselben <code>NvBlockDescriptor</code> in <code>NvBlockNeeds</code> mehrere event-basierte Speicherstrategien (<code>storeImmediately=True</code> und <code>storeAtShutdown=True</code>) gleichzeitig deklariert sind, <strong>muss</strong> für jedes beteiligte Datenelement ein <code>RoleBasedDataAssignment</code> mit den exakten normativen Rollennamen (<code>storeImmediately</code> bzw. <code>storeAtShutdown</code>) definiert werden. Fehlt diese Zuordnung, schlägt die Validierung des ARXML-Modells fehl, da der RTE-Generator das Verhalten nicht deterministisch auflösen kann.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Generatorkonsequenz:</strong></li>\n<li>Anhand der Rolle <code>storeImmediately</code> generiert die RTE in der zugehörigen Runnable (<code>Immediate</code>) bzw. im Komponenten-Wrapper den API-Aufruf zur Beauftragung des NvM.</li>\n<li>Fehlt das Mapping, generiert der Generator entweder redundante/zyklische Schreibzugriffe oder unterlässt den Sofortschreibauftrag vollständig.</li>\n<li><strong>Nebenläufigkeit & Datenintegrität (Concurrency):</strong></li>\n</ul>\n<p class=\"fig-p\">Da beide Runnables (<code>Shutdown</code> und <code>Immediate</code>) auf denselben RAM-Spiegel des <code>NvBlockDescriptor</code> schreiben, müssen im RTE-Vertrag Schutzmechanismen (z. B. <em>Exclusive Areas</em> / Inter-Runnable Resource Locks) konfiguriert werden, um Race Conditions und inkonsistente Zwischenstände bei gleichzeitiger Ausführung zu verhindern.</p>\n<ul class=\"fig-list\">\n<li><strong>Embedded Flash Endurance (Wear-Out):</strong></li>\n</ul>\n<p class=\"fig-p\">Port Y darf im Applikationsdesign nur für seltene, zwingend absturzfeste Events (z. B. Crash-Signale, kritische Fehler/DTCs, initiale Kalibrierungen) verwendet werden. Ein hochfrequentes Senden auf Port Y führt durch die <code>storeImmediately</code>-Eigenschaft zur schnellen Erschöpfung der Flash-Löschzyklen (Endurance Limit von EEPROM/Data-Flash). Port X ist für zyklisch/häufig fluktuierende Werte zu nutzen.</p>"}, {"id": "FIG-08281da991757506", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Instanzendiagramm / AUTOSAR-Objektdiagramm (M2/M1-Ausschnitt der Software Component Template, TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (VFB- und BSW-Interaktionsebene), Kapitel 11 (<em>NV Data Handling</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der formalen Disambiguierung für die RTE- und BSW-Generierung, wenn derselbe persistente Speicherblock (<code>NvBlockDescriptor</code>) über verschiedene Ports/Events mit divergierenden Persistierungsstrategien (sofortiges Schreiben vs. Schreiben beim Herunterfahren) angesteuert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>NvBlockSwComponentType</code>:</strong> Kapselnder SW-C-Typ, der den NVRAM-Blockzugriff und dessen RAM-Mirror verwaltet und Schnittstellen zu Application-SWCs und dem NVRAM Manager (NvM) bereitstellt.</li>\n<li><strong><code>NvBlockDescriptor</code> (Name: <code>\"nvBlock\"</code>):</strong> Zentrales Deskriptor-Element zur statischen Definition der NV-Blockeigenschaften innerhalb der SW-C.</li>\n<li>Aggregiert zwei <code>NvBlockDataMapping</code>-Instanzen (<code>\"X\"</code> und <code>\"Y\"</code>).</li>\n<li>Aggregiert zwei <code>RoleBasedDataAssignment</code>-Instanzen.</li>\n<li>Aggregiert / referenziert <code>NvBlockNeeds</code> (<code>\"nvBlock\"</code>).</li>\n<li><strong>Ports & Datenelemente (<code>DE1</code>):</strong></li>\n<li><strong>Port X (Blau):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Shutdown-Speicherung).</li>\n<li><strong>Port Y (Orange):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Sofortspeicherung).</li>\n<li><strong><code>NvBlockNeeds</code> (Name: <code>\"nvBlock\"</code>):</strong> BSW-Service-Bedarfsdeklaration an den NvM mit widersprüchlichen bzw. parallelen Anforderungen:</li>\n<li><code>storeAtShutdown = True</code></li>\n<li><code>storeImmediately = True</code></li>\n<li><strong><code>RoleBasedDataAssignment</code> (Disambiguierungs-Entitäten gem. <code>TPS_SWCT_01586</code>):</strong></li>\n<li><code>role = \"storeAtShutdown\"</code>: Bindet das Datenelement <code>DE1</code> von Port X an die Shutdown-Strategie von <code>NvBlockNeeds</code>.</li>\n<li><code>role = \"storeImmediately\"</code>: Bindet das Datenelement <code>DE1</code> von Port Y an die Immediate-Schreibstrategie von <code>NvBlockNeeds</code>.</li>\n<li><strong>RTE-Events & Runnables:</strong></li>\n<li><code>DataReceivedEvent</code> <code>\"X\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Shutdown\"</code> bei Datenempfang an Port X.</li>\n<li><code>DataReceivedEvent</code> <code>\"Y\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Immediate\"</code> bei Datenempfang an Port Y.</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>NvBlockDataMapping</code> (Mapping von mehreren Port-Datenelementen auf denselben NV-Block).</li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>RoleBasedDataAssignment</code> (Eindeutige Rollenzuweisung pro Port-Datenelement).</li>\n<li><code>DataReceivedEvent</code> referenziert das jeweilige <code>VariableDataPrototype</code> (<code>DE1</code>) am Port und triggert die zugeordnete <code>RunnableEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Pfad X: Pufferung / Store-at-Shutdown (Blau)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port X (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"X\"</code> löst <code>RunnableEntity \"Shutdown\"</code> aus.</li>\n<li><strong>RAM-Update:</strong> Die Runnable liest <code>DE1</code> via RTE-API und aktualisiert den lokalen RAM-Spiegel des <code>NvBlockDescriptor</code>.</li>\n<li><strong>Kein NvM-Trigger:</strong> Es wird <em>kein</em> Sofortschreibauftrag (<code>NvM_WriteBlock</code>) an den NvM abgesetzt.</li>\n<li><strong>Persistierung:</strong> Der Block wird erst im Steuergeräte-Nachlauf (ECU Shutdown via <code>BswM</code>/<code>EcuM</code>) über den globalen Sammelauftrag <code>NvM_WriteAll</code> in das nichtflüchtige Medium (Flash/EEPROM) geschrieben.</li>\n</ol>\n<p class=\"fig-p\">#### Pfad Y: Sofortige Persistierung / Store-Immediately (Orange)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port Y (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"Y\"</code> löst <code>RunnableEntity \"Immediate\"</code> aus.</li>\n<li><strong>RAM-Update & NvM-Schreibauftrag:</strong> Die Runnable liest <code>DE1</code>, aktualisiert den RAM-Spiegel und setzt über die RTE unmittelbar einen asynchronen Schreibauftrag (<code>NvM_WriteBlock</code> / Service-Port <code>NvMService</code>) ab.</li>\n<li><strong>Verarbeitung:</strong> Der NvM reiht den Request in seine interne Prioritäts-Queue ein und führt den Schreibvorgang via MemIf/Fee/Fls direkt im laufenden Betriebszyklus aus.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgabe (<code>TPS_SWCT_01586</code>):</strong></li>\n</ul>\n<p class=\"fig-p\">Wenn für denselben <code>NvBlockDescriptor</code> in <code>NvBlockNeeds</code> mehrere event-basierte Speicherstrategien (<code>storeImmediately=True</code> und <code>storeAtShutdown=True</code>) gleichzeitig deklariert sind, <strong>muss</strong> für jedes beteiligte Datenelement ein <code>RoleBasedDataAssignment</code> mit den exakten normativen Rollennamen (<code>storeImmediately</code> bzw. <code>storeAtShutdown</code>) definiert werden. Fehlt diese Zuordnung, schlägt die Validierung des ARXML-Modells fehl, da der RTE-Generator das Verhalten nicht deterministisch auflösen kann.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Generatorkonsequenz:</strong></li>\n<li>Anhand der Rolle <code>storeImmediately</code> generiert die RTE in der zugehörigen Runnable (<code>Immediate</code>) bzw. im Komponenten-Wrapper den API-Aufruf zur Beauftragung des NvM.</li>\n<li>Fehlt das Mapping, generiert der Generator entweder redundante/zyklische Schreibzugriffe oder unterlässt den Sofortschreibauftrag vollständig.</li>\n<li><strong>Nebenläufigkeit & Datenintegrität (Concurrency):</strong></li>\n</ul>\n<p class=\"fig-p\">Da beide Runnables (<code>Shutdown</code> und <code>Immediate</code>) auf denselben RAM-Spiegel des <code>NvBlockDescriptor</code> schreiben, müssen im RTE-Vertrag Schutzmechanismen (z. B. <em>Exclusive Areas</em> / Inter-Runnable Resource Locks) konfiguriert werden, um Race Conditions und inkonsistente Zwischenstände bei gleichzeitiger Ausführung zu verhindern.</p>\n<ul class=\"fig-list\">\n<li><strong>Embedded Flash Endurance (Wear-Out):</strong></li>\n</ul>\n<p class=\"fig-p\">Port Y darf im Applikationsdesign nur für seltene, zwingend absturzfeste Events (z. B. Crash-Signale, kritische Fehler/DTCs, initiale Kalibrierungen) verwendet werden. Ein hochfrequentes Senden auf Port Y führt durch die <code>storeImmediately</code>-Eigenschaft zur schnellen Erschöpfung der Flash-Löschzyklen (Endurance Limit von EEPROM/Data-Flash). Port X ist für zyklisch/häufig fluktuierende Werte zu nutzen.</p>"}, {"id": "FIG-0c8febd841a17a79", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Instanzendiagramm / AUTOSAR-Objektdiagramm (M2/M1-Ausschnitt der Software Component Template, TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (VFB- und BSW-Interaktionsebene), Kapitel 11 (<em>NV Data Handling</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der formalen Disambiguierung für die RTE- und BSW-Generierung, wenn derselbe persistente Speicherblock (<code>NvBlockDescriptor</code>) über verschiedene Ports/Events mit divergierenden Persistierungsstrategien (sofortiges Schreiben vs. Schreiben beim Herunterfahren) angesteuert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>NvBlockSwComponentType</code>:</strong> Kapselnder SW-C-Typ, der den NVRAM-Blockzugriff und dessen RAM-Mirror verwaltet und Schnittstellen zu Application-SWCs und dem NVRAM Manager (NvM) bereitstellt.</li>\n<li><strong><code>NvBlockDescriptor</code> (Name: <code>\"nvBlock\"</code>):</strong> Zentrales Deskriptor-Element zur statischen Definition der NV-Blockeigenschaften innerhalb der SW-C.</li>\n<li>Aggregiert zwei <code>NvBlockDataMapping</code>-Instanzen (<code>\"X\"</code> und <code>\"Y\"</code>).</li>\n<li>Aggregiert zwei <code>RoleBasedDataAssignment</code>-Instanzen.</li>\n<li>Aggregiert / referenziert <code>NvBlockNeeds</code> (<code>\"nvBlock\"</code>).</li>\n<li><strong>Ports & Datenelemente (<code>DE1</code>):</strong></li>\n<li><strong>Port X (Blau):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Shutdown-Speicherung).</li>\n<li><strong>Port Y (Orange):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Sofortspeicherung).</li>\n<li><strong><code>NvBlockNeeds</code> (Name: <code>\"nvBlock\"</code>):</strong> BSW-Service-Bedarfsdeklaration an den NvM mit widersprüchlichen bzw. parallelen Anforderungen:</li>\n<li><code>storeAtShutdown = True</code></li>\n<li><code>storeImmediately = True</code></li>\n<li><strong><code>RoleBasedDataAssignment</code> (Disambiguierungs-Entitäten gem. <code>TPS_SWCT_01586</code>):</strong></li>\n<li><code>role = \"storeAtShutdown\"</code>: Bindet das Datenelement <code>DE1</code> von Port X an die Shutdown-Strategie von <code>NvBlockNeeds</code>.</li>\n<li><code>role = \"storeImmediately\"</code>: Bindet das Datenelement <code>DE1</code> von Port Y an die Immediate-Schreibstrategie von <code>NvBlockNeeds</code>.</li>\n<li><strong>RTE-Events & Runnables:</strong></li>\n<li><code>DataReceivedEvent</code> <code>\"X\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Shutdown\"</code> bei Datenempfang an Port X.</li>\n<li><code>DataReceivedEvent</code> <code>\"Y\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Immediate\"</code> bei Datenempfang an Port Y.</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>NvBlockDataMapping</code> (Mapping von mehreren Port-Datenelementen auf denselben NV-Block).</li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>RoleBasedDataAssignment</code> (Eindeutige Rollenzuweisung pro Port-Datenelement).</li>\n<li><code>DataReceivedEvent</code> referenziert das jeweilige <code>VariableDataPrototype</code> (<code>DE1</code>) am Port und triggert die zugeordnete <code>RunnableEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Pfad X: Pufferung / Store-at-Shutdown (Blau)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port X (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"X\"</code> löst <code>RunnableEntity \"Shutdown\"</code> aus.</li>\n<li><strong>RAM-Update:</strong> Die Runnable liest <code>DE1</code> via RTE-API und aktualisiert den lokalen RAM-Spiegel des <code>NvBlockDescriptor</code>.</li>\n<li><strong>Kein NvM-Trigger:</strong> Es wird <em>kein</em> Sofortschreibauftrag (<code>NvM_WriteBlock</code>) an den NvM abgesetzt.</li>\n<li><strong>Persistierung:</strong> Der Block wird erst im Steuergeräte-Nachlauf (ECU Shutdown via <code>BswM</code>/<code>EcuM</code>) über den globalen Sammelauftrag <code>NvM_WriteAll</code> in das nichtflüchtige Medium (Flash/EEPROM) geschrieben.</li>\n</ol>\n<p class=\"fig-p\">#### Pfad Y: Sofortige Persistierung / Store-Immediately (Orange)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port Y (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"Y\"</code> löst <code>RunnableEntity \"Immediate\"</code> aus.</li>\n<li><strong>RAM-Update & NvM-Schreibauftrag:</strong> Die Runnable liest <code>DE1</code>, aktualisiert den RAM-Spiegel und setzt über die RTE unmittelbar einen asynchronen Schreibauftrag (<code>NvM_WriteBlock</code> / Service-Port <code>NvMService</code>) ab.</li>\n<li><strong>Verarbeitung:</strong> Der NvM reiht den Request in seine interne Prioritäts-Queue ein und führt den Schreibvorgang via MemIf/Fee/Fls direkt im laufenden Betriebszyklus aus.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgabe (<code>TPS_SWCT_01586</code>):</strong></li>\n</ul>\n<p class=\"fig-p\">Wenn für denselben <code>NvBlockDescriptor</code> in <code>NvBlockNeeds</code> mehrere event-basierte Speicherstrategien (<code>storeImmediately=True</code> und <code>storeAtShutdown=True</code>) gleichzeitig deklariert sind, <strong>muss</strong> für jedes beteiligte Datenelement ein <code>RoleBasedDataAssignment</code> mit den exakten normativen Rollennamen (<code>storeImmediately</code> bzw. <code>storeAtShutdown</code>) definiert werden. Fehlt diese Zuordnung, schlägt die Validierung des ARXML-Modells fehl, da der RTE-Generator das Verhalten nicht deterministisch auflösen kann.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Generatorkonsequenz:</strong></li>\n<li>Anhand der Rolle <code>storeImmediately</code> generiert die RTE in der zugehörigen Runnable (<code>Immediate</code>) bzw. im Komponenten-Wrapper den API-Aufruf zur Beauftragung des NvM.</li>\n<li>Fehlt das Mapping, generiert der Generator entweder redundante/zyklische Schreibzugriffe oder unterlässt den Sofortschreibauftrag vollständig.</li>\n<li><strong>Nebenläufigkeit & Datenintegrität (Concurrency):</strong></li>\n</ul>\n<p class=\"fig-p\">Da beide Runnables (<code>Shutdown</code> und <code>Immediate</code>) auf denselben RAM-Spiegel des <code>NvBlockDescriptor</code> schreiben, müssen im RTE-Vertrag Schutzmechanismen (z. B. <em>Exclusive Areas</em> / Inter-Runnable Resource Locks) konfiguriert werden, um Race Conditions und inkonsistente Zwischenstände bei gleichzeitiger Ausführung zu verhindern.</p>\n<ul class=\"fig-list\">\n<li><strong>Embedded Flash Endurance (Wear-Out):</strong></li>\n</ul>\n<p class=\"fig-p\">Port Y darf im Applikationsdesign nur für seltene, zwingend absturzfeste Events (z. B. Crash-Signale, kritische Fehler/DTCs, initiale Kalibrierungen) verwendet werden. Ein hochfrequentes Senden auf Port Y führt durch die <code>storeImmediately</code>-Eigenschaft zur schnellen Erschöpfung der Flash-Löschzyklen (Endurance Limit von EEPROM/Data-Flash). Port X ist für zyklisch/häufig fluktuierende Werte zu nutzen.</p>"}, {"id": "FIG-0c9269da77d788f7", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Metamodell-Instanzendiagramm / AUTOSAR-Objektdiagramm (M2/M1-Ausschnitt der Software Component Template, TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (VFB- und BSW-Interaktionsebene), Kapitel 11 (<em>NV Data Handling</em>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der formalen Disambiguierung für die RTE- und BSW-Generierung, wenn derselbe persistente Speicherblock (<code>NvBlockDescriptor</code>) über verschiedene Ports/Events mit divergierenden Persistierungsstrategien (sofortiges Schreiben vs. Schreiben beim Herunterfahren) angesteuert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>NvBlockSwComponentType</code>:</strong> Kapselnder SW-C-Typ, der den NVRAM-Blockzugriff und dessen RAM-Mirror verwaltet und Schnittstellen zu Application-SWCs und dem NVRAM Manager (NvM) bereitstellt.</li>\n<li><strong><code>NvBlockDescriptor</code> (Name: <code>\"nvBlock\"</code>):</strong> Zentrales Deskriptor-Element zur statischen Definition der NV-Blockeigenschaften innerhalb der SW-C.</li>\n<li>Aggregiert zwei <code>NvBlockDataMapping</code>-Instanzen (<code>\"X\"</code> und <code>\"Y\"</code>).</li>\n<li>Aggregiert zwei <code>RoleBasedDataAssignment</code>-Instanzen.</li>\n<li>Aggregiert / referenziert <code>NvBlockNeeds</code> (<code>\"nvBlock\"</code>).</li>\n<li><strong>Ports & Datenelemente (<code>DE1</code>):</strong></li>\n<li><strong>Port X (Blau):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Shutdown-Speicherung).</li>\n<li><strong>Port Y (Orange):</strong> R-Port/Empfangsport für Datenelement <code>DE1</code> (Pfad: Sofortspeicherung).</li>\n<li><strong><code>NvBlockNeeds</code> (Name: <code>\"nvBlock\"</code>):</strong> BSW-Service-Bedarfsdeklaration an den NvM mit widersprüchlichen bzw. parallelen Anforderungen:</li>\n<li><code>storeAtShutdown = True</code></li>\n<li><code>storeImmediately = True</code></li>\n<li><strong><code>RoleBasedDataAssignment</code> (Disambiguierungs-Entitäten gem. <code>TPS_SWCT_01586</code>):</strong></li>\n<li><code>role = \"storeAtShutdown\"</code>: Bindet das Datenelement <code>DE1</code> von Port X an die Shutdown-Strategie von <code>NvBlockNeeds</code>.</li>\n<li><code>role = \"storeImmediately\"</code>: Bindet das Datenelement <code>DE1</code> von Port Y an die Immediate-Schreibstrategie von <code>NvBlockNeeds</code>.</li>\n<li><strong>RTE-Events & Runnables:</strong></li>\n<li><code>DataReceivedEvent</code> <code>\"X\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Shutdown\"</code> bei Datenempfang an Port X.</li>\n<li><code>DataReceivedEvent</code> <code>\"Y\"</code>: Aktiviert <code>RunnableEntity</code> <code>\"Immediate\"</code> bei Datenempfang an Port Y.</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>NvBlockDataMapping</code> (Mapping von mehreren Port-Datenelementen auf denselben NV-Block).</li>\n<li><code>NvBlockDescriptor</code> $\\xrightarrow{1..\\ast}$ <code>RoleBasedDataAssignment</code> (Eindeutige Rollenzuweisung pro Port-Datenelement).</li>\n<li><code>DataReceivedEvent</code> referenziert das jeweilige <code>VariableDataPrototype</code> (<code>DE1</code>) am Port und triggert die zugeordnete <code>RunnableEntity</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Pfad X: Pufferung / Store-at-Shutdown (Blau)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port X (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"X\"</code> löst <code>RunnableEntity \"Shutdown\"</code> aus.</li>\n<li><strong>RAM-Update:</strong> Die Runnable liest <code>DE1</code> via RTE-API und aktualisiert den lokalen RAM-Spiegel des <code>NvBlockDescriptor</code>.</li>\n<li><strong>Kein NvM-Trigger:</strong> Es wird <em>kein</em> Sofortschreibauftrag (<code>NvM_WriteBlock</code>) an den NvM abgesetzt.</li>\n<li><strong>Persistierung:</strong> Der Block wird erst im Steuergeräte-Nachlauf (ECU Shutdown via <code>BswM</code>/<code>EcuM</code>) über den globalen Sammelauftrag <code>NvM_WriteAll</code> in das nichtflüchtige Medium (Flash/EEPROM) geschrieben.</li>\n</ol>\n<p class=\"fig-p\">#### Pfad Y: Sofortige Persistierung / Store-Immediately (Orange)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Datenankunft am R-Port Y (<code>DE1</code>).</li>\n<li><strong>RTE-Aktivierung:</strong> <code>DataReceivedEvent \"Y\"</code> löst <code>RunnableEntity \"Immediate\"</code> aus.</li>\n<li><strong>RAM-Update & NvM-Schreibauftrag:</strong> Die Runnable liest <code>DE1</code>, aktualisiert den RAM-Spiegel und setzt über die RTE unmittelbar einen asynchronen Schreibauftrag (<code>NvM_WriteBlock</code> / Service-Port <code>NvMService</code>) ab.</li>\n<li><strong>Verarbeitung:</strong> Der NvM reiht den Request in seine interne Prioritäts-Queue ein und führt den Schreibvorgang via MemIf/Fee/Fls direkt im laufenden Betriebszyklus aus.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgabe (<code>TPS_SWCT_01586</code>):</strong></li>\n</ul>\n<p class=\"fig-p\">Wenn für denselben <code>NvBlockDescriptor</code> in <code>NvBlockNeeds</code> mehrere event-basierte Speicherstrategien (<code>storeImmediately=True</code> und <code>storeAtShutdown=True</code>) gleichzeitig deklariert sind, <strong>muss</strong> für jedes beteiligte Datenelement ein <code>RoleBasedDataAssignment</code> mit den exakten normativen Rollennamen (<code>storeImmediately</code> bzw. <code>storeAtShutdown</code>) definiert werden. Fehlt diese Zuordnung, schlägt die Validierung des ARXML-Modells fehl, da der RTE-Generator das Verhalten nicht deterministisch auflösen kann.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Generatorkonsequenz:</strong></li>\n<li>Anhand der Rolle <code>storeImmediately</code> generiert die RTE in der zugehörigen Runnable (<code>Immediate</code>) bzw. im Komponenten-Wrapper den API-Aufruf zur Beauftragung des NvM.</li>\n<li>Fehlt das Mapping, generiert der Generator entweder redundante/zyklische Schreibzugriffe oder unterlässt den Sofortschreibauftrag vollständig.</li>\n<li><strong>Nebenläufigkeit & Datenintegrität (Concurrency):</strong></li>\n</ul>\n<p class=\"fig-p\">Da beide Runnables (<code>Shutdown</code> und <code>Immediate</code>) auf denselben RAM-Spiegel des <code>NvBlockDescriptor</code> schreiben, müssen im RTE-Vertrag Schutzmechanismen (z. B. <em>Exclusive Areas</em> / Inter-Runnable Resource Locks) konfiguriert werden, um Race Conditions und inkonsistente Zwischenstände bei gleichzeitiger Ausführung zu verhindern.</p>\n<ul class=\"fig-list\">\n<li><strong>Embedded Flash Endurance (Wear-Out):</strong></li>\n</ul>\n<p class=\"fig-p\">Port Y darf im Applikationsdesign nur für seltene, zwingend absturzfeste Events (z. B. Crash-Signale, kritische Fehler/DTCs, initiale Kalibrierungen) verwendet werden. Ein hochfrequentes Senden auf Port Y führt durch die <code>storeImmediately</code>-Eigenschaft zur schnellen Erschöpfung der Flash-Löschzyklen (Endurance Limit von EEPROM/Data-Flash). Port X ist für zyklisch/häufig fluktuierende Werte zu nutzen.</p>"}], "trans": [{"from": "FIG-03c3afffec9b27c2", "to": "FIG-419831fa6ee6f5c9", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>NvBlockNeeds</code>: Schreibweise der booleschen Attributwerte von <code>storeAtShutdown=True</code> und <code>storeImmediately=True</code> auf Kleinschreibung (<code>true</code>) umgestellt.</li>\n<li><code>NvBlockDescriptor</code>: Darstellung der Aggregationsrauten zu <code>NvBlockDataMapping</code>, <code>RoleBasedDataAssignment</code> und <code>NvBlockNeeds</code> von offenen Rauten auf ausgefüllte Kompositionsrauten umgestellt.</li>\n<li>Diagramm-Layout: Vertikale Anordnung kompaktiert und Gesamthöhe verringert.</li>\n</ul>"}, {"from": "FIG-419831fa6ee6f5c9", "to": "FIG-08281da991757506", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-08281da991757506", "to": "FIG-0c8febd841a17a79", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0c8febd841a17a79", "to": "FIG-0c9269da77d788f7", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>NvBlockDescriptor</code>: Alle Verbindungslinien (Kompositions- und Assoziationspfeile) zu <code>NvBlockDataMapping</code>, <code>RoleBasedDataAssignment</code> und <code>NvBlockNeeds</code> wurden entfernt.</li>\n<li><code>NvBlockDataMapping</code>: Typografischer Fehler in der Beschriftung der oberen Instanz (<code>NvBlockDataMappingc\"X\"</code> statt <code>NvBlockDataMapping</code> und <code>\"X\"</code>).</li>\n<li><code>DataReceivedEvent</code>: Beschriftungen für <code>\"X\"</code> und <code>\"Y\"</code> wurden von zweizeiliger auf einzeilige Darstellung umgestellt.</li>\n<li><code>NvBlockDataMapping</code>: Beschriftung für Instanz <code>\"Y\"</code> wurde von zweizeiliger auf einzeilige Darstellung umgestellt.</li>\n<li>Diagramm-Layout: Abmessungen und Seitenverhältnis angepasst.</li>\n</ul>"}]};
